CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY,data_json TEXT NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,week INTEGER NOT NULL,day TEXT NOT NULL,title TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,periods INTEGER NOT NULL DEFAULT 1,room TEXT,color TEXT,type TEXT,data_json TEXT,updated_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS schedules (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,week INTEGER NOT NULL,data_json TEXT NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(user_id,week));
CREATE TABLE IF NOT EXISTS checkins (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,date_key TEXT NOT NULL,item_key TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(user_id,date_key,item_key));
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_courses_user_week ON courses(user_id,week);
CREATE INDEX IF NOT EXISTS idx_checkins_user_date ON checkins(user_id,date_key);